ROOT=Path(__file__).resolve().parents[2];BASE=ROOT/'tools/scripts/run_e113_formal_three_dataset_meta_audit.py';OUT=ROOT/'docs/实验结果/E124_formal_five_dataset_meta_20260714';TABLES=OUT/'tables';REPORTS=OUT/'reports';FIGURES=OUT/'figures'
def module():
 s=importlib.util.spec_from_file_location('e113_for_e124',BASE);m=importlib.util.module_from_spec(s);sys.modules[s.name]=m;s.loader.exec_module(m);m.N_BOOT=2000;return m
def load():
 a=pd.read_csv(ROOT/'docs/实验结果/E108_formal_dual_model_risk_audit_20260713/tables/E108_TEST_TASK_RISK_TABLE.csv');a['dataset']='Frangieh';b=pd.read_csv(ROOT/'docs/实验结果/E112_external_formal_dual_models_20260713/E112_ALL_TASKS.csv');c=pd.read_csv(ROOT/'docs/实验结果/E120_shifrut_formal_dual_models_20260714/Shifrut/TASK_RISK_TABLE.csv');c['dataset']='Shifrut';d=pd.read_csv(ROOT/'docs/实验结果/E123_liang_formal_dual_models_20260714/Liang/TASK_RISK_TABLE.csv');d['dataset']='Liang';return pd.concat([a,b,c,d],ignore_index=True,sort=False)
def figure(boot):
 d=boot[(boot.target=='error_two_predictor_mean_rmse')&(boot.comparator=='baseline_predicted_magnitude')&boot.unit.isin(['outer_fold_plus_perturbation_cluster','fixed_five_datasets'])].copy();order=['Frangieh','Lara_exvivo','Santinha','Shifrut','Liang','five_dataset_macro'];d['o']=d.scope.map({x:i for i,x in enumerate(order)});d=d.sort_values('o');w,h,left,right=1100,610,260,80;lo,hi=-.45,.45;sx=lambda v:left+(v-lo)/(hi-lo)*(w-left-right);parts=[f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}">','<rect width="100%" height="100%" fill="#fff"/>','<style>text{font-family:Arial,"Noto Sans CJK SC",sans-serif;fill:#27343c}.t{font-size:24px;font-weight:700}.s{font-size:13px;fill:#647078}.l{font-size:15px}</style>','<text x="45" y="40" class="t">E124｜五正式数据集：SafeConf 相对 magnitude</text>','<text x="45" y="67" class="s">Shifrut 与 Liang 在前三数据集主分析后冻结；点为 fold 宏平均 Δρ，线为聚类 bootstrap 95% CI。</text>',f'<line x1="{sx(0):.1f}" y1="90" x2="{sx(0):.1f}" y2="555" stroke="#89959b" stroke-dasharray="5 5"/>']
