  y=120+i*72;label='五数据集固定集合' if r.scope=='five_dataset_macro' else r.scope;parts += [f'<text x="45" y="{y+5}" class="l">{label}</text>',f'<line x1="{sx(r.ci95_low):.1f}" y1="{y}" x2="{sx(r.ci95_high):.1f}" y2="{y}" stroke="#396d83" stroke-width="4"/>',f'<circle cx="{sx(r.delta):.1f}" cy="{y}" r="7" fill="#285f78"/>',f'<text x="{w-30}" y="{y+5}" text-anchor="end" class="s">{r.delta:.3f} [{r.ci95_low:.3f}, {r.ci95_high:.3f}]</text>']
