 for r in pivot.itertuples(index=False):lines.append(f'| {r.dataset} | {r.safeconf_calibrated_pair_risk:.3f} | {r.safeconf_frozen_pair_risk:.3f} | {r.risk_model_disagreement:.3f} | {r.baseline_predicted_magnitude:.3f} |')
 lines += ['','## Bootstrap','','| scope | comparator | unit | Δρ | 95% CI | P(Δ>0) |','|---|---|---|---:|---:|---:|']
 for r in b.itertuples(index=False):lines.append(f'| {r.scope} | {r.comparator} | {r.unit} | {r.delta:.3f} | [{r.ci95_low:.3f}, {r.ci95_high:.3f}] | {r.p_gt_zero:.3f} |')
 lines += ['','Shifrut 中 SafeConf 没有超过 magnitude，Liang 则形成新的正复制。两者均保留在总体推断中，不按结果删除。五数据集总体结论优先于 E113 的三数据集结论。'];(REPORTS/'E124_REPORT.md').write_text('\n'.join(lines)+'\n');(OUT/'README_先看这个.md').write_text('# E124 先看这个\n\n先读 `reports/E124_REPORT.md`。\n');print(json.dumps(status,ensure_ascii=False,indent=2));print(pivot.to_string(index=False));print(b[b.scope.eq('five_dataset_macro')].to_string(index=False))
